/**
 * `omg factory setup --workflows`: renders the cloud heartbeat (a scheduled
 * GitHub workflow, or an Azure DevOps pipeline) from templates/workflows and
 * templates/pipelines, and plans its single file.
 *
 * Safety shape: the generated file runs only `omg factory check` (and, in
 * triage mode, `omg factory triage --apply`), pinned to the installed package
 * version, with read-only permissions unless triage mode asks for a write
 * scope. A file this command did not write (no marker line) is never replaced
 * without `force`; nothing outside the one target path is written.
 */

import { existsSync, lstatSync, readFileSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';
import { SetupError } from './guard.js';
import { lineDiff, type PlannedWrite } from './write.js';

export type HeartbeatMode = 'read-only' | 'triage';
export type HeartbeatForge = 'github' | 'azure-devops';

export const DEFAULT_HEARTBEAT_CRON = '17 */2 * * *';
export const HEARTBEAT_MARKER = '# omg-factory-heartbeat: generated by `omg factory setup --workflows`';

const TARGETS: Record<HeartbeatForge, { path: string; template: string; step: string; dir: string }> = {
  github: { path: '.github/workflows/omg-factory-heartbeat.yml', template: 'omg-factory-heartbeat.yml', step: 'omg-factory-heartbeat.triage-step.yml', dir: 'workflows' },
  'azure-devops': { path: '.azure-pipelines/omg-factory-heartbeat.yml', template: 'omg-factory-heartbeat.azure-pipelines.yml', step: 'omg-factory-heartbeat.triage-step.yml', dir: 'pipelines' },
};

export interface HeartbeatOptions {
  mode: HeartbeatMode;
  cron: string;
  /** The exact package version the generated file installs. */
  version: string;
  force: boolean;
}

export interface HeartbeatPlan {
  /** Repository-relative target path (forward slashes). */
  relPath: string;
  write?: PlannedWrite;
  /** `create`, `update` (a file we wrote), `overwrite` (foreign, --force) or `unchanged`. */
  action: 'create' | 'update' | 'overwrite' | 'unchanged';
}

const CRON = /^(?:[0-9*/,-]+ ){4}[0-9*/,-]+$/;
const VERSION = /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/;

export function parseHeartbeatMode(raw: string | undefined): HeartbeatMode {
  if (raw === undefined || raw === 'read-only') return 'read-only';
  if (raw === 'triage') return 'triage';
  throw new SetupError(2, `--mode must be read-only or triage, got ${JSON.stringify(raw)}`);
}

export function heartbeatPath(forge: HeartbeatForge): string {
  return TARGETS[forge].path;
}

/** templates/<dir> of the package, found by walking up from this module (src/, dist/ or the bundle). */
function templateDir(dir: string): string {
  let here = dirname(fileURLToPath(import.meta.url));
  for (let i = 0; i < 6; i++) {
    const candidate = join(here, 'templates', dir);
    if (existsSync(candidate)) return candidate;
    here = dirname(here);
  }
  throw new SetupError(1, `cannot find the packaged templates/${dir} directory`);
}

/** The rendered file; inputs are validated first because they land in YAML. */
export function renderHeartbeat(forge: HeartbeatForge, o: Pick<HeartbeatOptions, 'mode' | 'cron' | 'version'>): string {
  if (!CRON.test(o.cron)) throw new SetupError(2, `--cron must be five cron fields (digits, *, /, comma, dash), got ${JSON.stringify(o.cron)}`);
  if (!VERSION.test(o.version)) throw new SetupError(1, `cannot pin the omg version ${JSON.stringify(o.version)}: not an exact semver`);
  const target = TARGETS[forge];
  const dir = templateDir(target.dir);
  const template = readFileSync(join(dir, target.template), 'utf8').replace(/\r\n/g, '\n');
  const triage = o.mode === 'triage';
  const note = triage
    ? forge === 'github'
      ? '#   Triage mode is the opt-in write scope: issues: write lets `omg factory triage --apply` set labels.\n'
      : '# Triage mode is the opt-in write scope: `omg factory triage --apply` sets tags, so the build identity needs work item write access.\n'
    : '';
  const stepText = triage ? readFileSync(join(dir, target.step), 'utf8').replace(/\r\n/g, '\n') : '';
  const out = template
    .split('@@TRIAGE_STEP@@\n').join(stepText)
    // GitHub only: the read-only file has no triage step, so it must not reference one.
    .split('@@TRIAGE_ENV@@').join(triage ? '          TRIAGE_CODE: ${{ steps.triage.outputs.code }}\n' : '')
    .split('@@MODE_NOTE@@').join(note)
    .split('@@ISSUES@@').join(triage ? 'write' : 'read')
    .split('@@MODE@@').join(o.mode)
    .split('@@CRON@@').join(o.cron)
    .split('@@VERSION@@').join(o.version);
  if (out.includes('@@')) throw new SetupError(1, 'heartbeat template has an unfilled placeholder');
  return out;
}

/** Plans the one file. Throws SetupError(5) when a file we did not write is in the way and force is off. */
export function planHeartbeat(root: string, forge: HeartbeatForge, o: HeartbeatOptions): HeartbeatPlan {
  const relPath = TARGETS[forge].path;
  const after = renderHeartbeat(forge, o);
  const path = join(root, ...relPath.split('/'));
  // Every directory on the way, and the file, must be a real one: a link would redirect the write.
  let p = root;
  for (const seg of relPath.split('/')) {
    p = join(p, seg);
    if (existsSync(p) && lstatSync(p).isSymbolicLink()) throw new SetupError(5, `refusing to write ${relPath}: ${p} is a symlink or junction`);
  }
  if (!existsSync(path)) return { relPath, action: 'create', write: { path, scope: 'project', before: '', after, diff: lineDiff('', after) } };
  const raw = readFileSync(path, 'utf8');
  const before = raw.replace(/\r\n/g, '\n');
  if (before === after) return { relPath, action: 'unchanged' };
  const ours = before.split('\n').some((line) => line.startsWith(HEARTBEAT_MARKER));
  if (!ours && !o.force) throw new SetupError(5, `${relPath} exists and was not written by omg factory setup --workflows; nothing written (pass --force to replace it)`);
  return { relPath, action: ours ? 'update' : 'overwrite', write: { path, scope: 'project', before: raw, after, diff: lineDiff(before, after) } };
}
